//! semver-sort: sort the lines of a workspace file by SemVer 2.0.0 precedence.
//!
//! Precedence rules (semver.org §11), implemented strictly:
//! - major, minor, patch compared numerically;
//! - a pre-release version has lower precedence than the same version without one;
//! - pre-release identifiers are compared dot-separated, left to right: two numeric
//!   identifiers numerically, two alphanumeric ones in ASCII order, numeric < alphanumeric;
//!   a larger set of fields wins when all preceding fields are equal;
//! - build metadata is ignored, so build-only variants tie and keep input order (stable sort).
#![cfg_attr(not(target_arch = "wasm32"), allow(dead_code))]

use std::cmp::Ordering;

use serde::Deserialize;
use serde_json::json;

const NAME: &str = "semver-sort";
const VERSION: &str = env!("CARGO_PKG_VERSION");

const DESCRIPTION: &str = "Sort the non-empty lines of a workspace file by SemVer 2.0.0 precedence \
(major, minor, patch, then pre-release identifiers; build metadata ignored). Optionally write the \
sorted lines to another workspace file. Returns {\"count\": n, \"sorted\": [...], \
\"equal_precedence\": [[versions sharing one precedence], ...]}.";

const SCHEMA: &str = r#"{
  "type": "object",
  "properties": {
    "path": {"type": "string", "description": "Input file, relative to the workspace, e.g. \"work/a2/versions.txt\""},
    "out":  {"type": "string", "description": "Optional output file, relative to the workspace; the sorted lines are written there with a trailing newline"}
  },
  "required": ["path"],
  "additionalProperties": false
}"#;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Input {
    path: String,
    #[serde(default)]
    out: Option<String>,
}

#[derive(Debug, PartialEq, Eq)]
enum Ident {
    Num(u64),
    Alpha(String),
}

#[derive(Debug, PartialEq, Eq)]
struct Version {
    major: u64,
    minor: u64,
    patch: u64,
    pre: Vec<Ident>,
}

fn is_ident_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || c == '-'
}

/// A numeric field: ASCII digits only, no leading zero unless the field is exactly "0".
fn parse_num(part: &str, whole: &str) -> Result<u64, String> {
    if part.is_empty() || !part.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!("{whole}: not a number: {part:?}"));
    }
    if part.len() > 1 && part.starts_with('0') {
        return Err(format!("{whole}: leading zero in {part:?}"));
    }
    part.parse::<u64>()
        .map_err(|_| format!("{whole}: number too large: {part:?}"))
}

/// A dot-separated [0-9A-Za-z-]+ list; empty identifiers are an error.
fn parse_dotted(part: &str, whole: &str, what: &str) -> Result<Vec<&str>, String> {
    if part.is_empty() {
        return Err(format!("{whole}: empty {what}"));
    }
    let ids: Vec<&str> = part.split('.').collect();
    for id in &ids {
        if id.is_empty() || !id.chars().all(is_ident_char) {
            return Err(format!("{whole}: bad {what} identifier {id:?}"));
        }
    }
    Ok(ids)
}

fn parse_pre(part: &str, whole: &str) -> Result<Vec<Ident>, String> {
    parse_dotted(part, whole, "pre-release")?
        .into_iter()
        .map(|id| {
            if id.bytes().all(|b| b.is_ascii_digit()) {
                parse_num(id, whole).map(Ident::Num)
            } else {
                Ok(Ident::Alpha(id.to_string()))
            }
        })
        .collect()
}

impl Version {
    fn parse(s: &str) -> Result<Version, String> {
        let whole = s.trim();
        if whole.is_empty() {
            return Err("empty version".into());
        }
        // Split off build metadata first: it is ignored, but must be well formed.
        let (rest, build) = match whole.split_once('+') {
            Some((r, b)) => (r, Some(b)),
            None => (whole, None),
        };
        if let Some(b) = build {
            parse_dotted(b, whole, "build metadata")?;
        }
        let (core, pre) = match rest.split_once('-') {
            Some((c, p)) => (c, Some(p)),
            None => (rest, None),
        };
        let fields: Vec<&str> = core.split('.').collect();
        if fields.len() != 3 {
            return Err(format!("{whole}: expected major.minor.patch"));
        }
        let pre = match pre {
            Some(p) => parse_pre(p, whole)?,
            None => Vec::new(),
        };
        Ok(Version {
            major: parse_num(fields[0], whole)?,
            minor: parse_num(fields[1], whole)?,
            patch: parse_num(fields[2], whole)?,
            pre,
        })
    }
}

fn cmp_ident(a: &Ident, b: &Ident) -> Ordering {
    match (a, b) {
        (Ident::Num(x), Ident::Num(y)) => x.cmp(y),
        // Numeric identifiers always have lower precedence than alphanumeric ones.
        (Ident::Num(_), Ident::Alpha(_)) => Ordering::Less,
        (Ident::Alpha(_), Ident::Num(_)) => Ordering::Greater,
        (Ident::Alpha(x), Ident::Alpha(y)) => x.cmp(y),
    }
}

impl Ord for Version {
    fn cmp(&self, other: &Self) -> Ordering {
        self.major
            .cmp(&other.major)
            .then(self.minor.cmp(&other.minor))
            .then(self.patch.cmp(&other.patch))
            .then_with(|| match (self.pre.is_empty(), other.pre.is_empty()) {
                (true, true) => Ordering::Equal,
                // A pre-release has lower precedence than the plain release.
                (true, false) => Ordering::Greater,
                (false, true) => Ordering::Less,
                (false, false) => {
                    for (a, b) in self.pre.iter().zip(other.pre.iter()) {
                        match cmp_ident(a, b) {
                            Ordering::Equal => continue,
                            other => return other,
                        }
                    }
                    self.pre.len().cmp(&other.pre.len())
                }
            })
    }
}

impl PartialOrd for Version {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

/// Pure logic: sort `lines` by precedence; return the sorted list and any equal-precedence groups.
fn sort_lines(lines: &[&str]) -> Result<(Vec<String>, Vec<Vec<String>>), String> {
    let mut parsed = Vec::with_capacity(lines.len());
    let mut bad = Vec::new();
    for line in lines {
        let s = line.trim();
        if s.is_empty() {
            continue;
        }
        match Version::parse(s) {
            Ok(v) => parsed.push((v, s.to_string())),
            Err(e) => bad.push(e),
        }
    }
    if !bad.is_empty() {
        return Err(format!("invalid version input: {}", bad.join("; ")));
    }
    // Stable: versions that differ only in build metadata keep their input order.
    parsed.sort_by(|a, b| a.0.cmp(&b.0));
    let mut groups: Vec<Vec<String>> = Vec::new();
    for pair in parsed.windows(2) {
        if pair[0].0 == pair[1].0 {
            match groups.last_mut() {
                Some(g) if g.len() >= 2 && g[g.len() - 2] == pair[0].1 => g.push(pair[1].1.clone()),
                _ => groups.push(vec![pair[0].1.clone(), pair[1].1.clone()]),
            }
        }
    }
    Ok((parsed.into_iter().map(|(_, s)| s).collect(), groups))
}

fn check_rel(p: &str) -> Result<(), String> {
    if p.starts_with('/') || p.split('/').any(|c| c == "..") || p.is_empty() {
        return Err(format!("path must be relative to the workspace: {p}"));
    }
    Ok(())
}

fn run(input: &str) -> Result<String, Fail> {
    let input: Input = serde_json::from_str(input).map_err(|e| Fail::Input(e.to_string()))?;
    check_rel(&input.path).map_err(Fail::Input)?;
    if let Some(out) = &input.out {
        check_rel(out).map_err(Fail::Input)?;
    }
    let full = format!("/work/{}", input.path);
    let text = std::fs::read_to_string(&full).map_err(|e| Fail::Run(format!("{full}: {e}")))?;
    let lines: Vec<&str> = text.lines().collect();
    let (sorted, equal) = sort_lines(&lines).map_err(Fail::Run)?;
    if let Some(out) = &input.out {
        let body = format!("{}\n", sorted.join("\n"));
        let path = format!("/work/{out}");
        if let Some(dir) = std::path::Path::new(&path).parent() {
            std::fs::create_dir_all(dir).map_err(|e| Fail::Run(format!("{}: {e}", dir.display())))?;
        }
        std::fs::write(&path, body).map_err(|e| Fail::Run(format!("{path}: {e}")))?;
    }
    Ok(json!({
        "count": sorted.len(),
        "sorted": sorted,
        "equal_precedence": equal,
    })
    .to_string())
}

enum Fail {
    Input(String),
    Run(String),
}

#[cfg(target_arch = "wasm32")]
mod bindings {
    wit_bindgen::generate!({
        path: "../../wit/init-ext/v1",
        world: "init:ext/tool",
    });

    use super::{DESCRIPTION, Fail, NAME, SCHEMA, VERSION};

    struct Component;

    impl Guest for Component {
        fn describe() -> ToolInfo {
            ToolInfo {
                name: NAME.to_string(),
                description: DESCRIPTION.to_string(),
                input_schema: SCHEMA.to_string(),
                version: VERSION.to_string(),
                timeout_ms: None,
            }
        }

        fn call(input: String) -> Result<String, ToolError> {
            super::run(&input).map_err(|f| match f {
                Fail::Input(m) => ToolError::InvalidInput(m),
                Fail::Run(m) => ToolError::Failed(m),
            })
        }
    }

    export!(Component);
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    fn sorted(lines: &[&str]) -> Vec<String> {
        sort_lines(lines).expect("valid input").0
    }

    #[test]
    fn spec_example_order() {
        // semver.org §11 example: already in precedence order.
        let v = [
            "1.0.0-alpha",
            "1.0.0-alpha.1",
            "1.0.0-alpha.beta",
            "1.0.0-beta",
            "1.0.0-beta.2",
            "1.0.0-beta.11",
            "1.0.0-rc.1",
            "1.0.0",
        ];
        let mut rev: Vec<&str> = v.to_vec();
        rev.reverse();
        assert_eq!(sorted(&rev), v);
        assert_eq!(sorted(&v), v);
    }

    #[test]
    fn numeric_fields_are_numeric() {
        assert_eq!(sorted(&["9.10.1", "10.0.0", "9.2.0"]), ["9.2.0", "9.10.1", "10.0.0"]);
        assert_eq!(sorted(&["7.0.0-11", "7.0.0-2"]), ["7.0.0-2", "7.0.0-11"]);
    }

    #[test]
    fn alphanumeric_vs_numeric_identifiers() {
        // numeric < alphanumeric; fewer fields first when one is a prefix.
        assert_eq!(
            sorted(&["1.2.4-a.0", "1.2.4-a", "1.2.4-0.a", "1.2.4-0"]),
            ["1.2.4-0", "1.2.4-0.a", "1.2.4-a", "1.2.4-a.0"]
        );
        assert_eq!(
            sorted(&["3.0.0-x-y-z.1", "3.0.0-x.7.z.92"]),
            ["3.0.0-x.7.z.92", "3.0.0-x-y-z.1"]
        );
    }

    #[test]
    fn build_metadata_is_ignored_and_ties_reported() {
        let v = ["1.2.3+build.42", "1.2.3", "4.5.6-beta+exp.sha.5114f85", "4.5.6"];
        let (out, eq) = sort_lines(&v).unwrap();
        // Stable: the earlier input line of a tie comes first.
        assert_eq!(out, ["1.2.3+build.42", "1.2.3", "4.5.6-beta+exp.sha.5114f85", "4.5.6"]);
        assert_eq!(eq, vec![vec!["1.2.3+build.42".to_string(), "1.2.3".to_string()]]);
    }

